import React, { useState, useEffect } from 'react';
import { router } from '@inertiajs/react';
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogFooter,
} from '@/Components/ui/dialog';
import { Button } from '@/Components/ui/button';
import { Input } from '@/Components/ui/input';
import { Label } from '@/Components/ui/label';
import { Textarea } from '@/Components/ui/textarea';
import { __ } from '@/lib/i18n';
import { Sparkles, Loader2, FileText, Plus, Trash2, Send } from 'lucide-react';
import axios from 'axios';

export default function ContractModal({ isOpen, onClose, project, contract, currencies }) {
    const [isLoading, setIsLoading] = useState(false);
    const [isGenerating, setIsGenerating] = useState(false);

    const [formData, setFormData] = useState({
        description: '',
        payment_terms: '',
        terms: '',
        notes: '',
        duration: '',
        valid_until: '',
        total_amount: '',
        currency_id: project.client?.currency_id || '',
        key_features: [] as string[],
        pricing_items: [] as any[],
        status: 'draft',
    });

    const [aiPrompt, setAiPrompt] = useState('');
    const [activeTab, setActiveTab] = useState('details'); // details, scope, pricing

    useEffect(() => {
        if (contract) {
            setFormData({
                description: contract.description || '',
                payment_terms: contract.payment_terms || '',
                terms: contract.content?.terms || '',
                notes: contract.content?.notes || '',
                duration: contract.content?.duration || '',
                valid_until: contract.valid_until ? contract.valid_until.split('T')[0] : '',
                total_amount: contract.total_amount || '',
                currency_id: contract.currency_id || '',
                key_features: contract.content?.key_features || [],
                pricing_items: contract.content?.pricing_items || [],
                status: contract.status || 'draft',
            });
        } else {
            setFormData({
                description: '',
                payment_terms: '',
                terms: '',
                notes: '',
                duration: '',
                valid_until: '',
                total_amount: '',
                currency_id: project.client?.currency_id || '',
                key_features: [],
                pricing_items: [],
                status: 'draft',
            });
            setAiPrompt('');
        }
        setActiveTab('details');
    }, [contract, isOpen]);

    const handleGenerateAi = async () => {
        if (!aiPrompt) return alert('Please enter requirements for the AI to generate the contract.');
        setIsGenerating(true);
        try {
            const res = await axios.post('/contracts/ai/generate', {
                project_id: project.id,
                prompt: aiPrompt,
            });

            const data = res.data;
            // The AI should return structured data. Merge it into form data.
            setFormData(prev => ({
                ...prev,
                description: data.description || prev.description,
                payment_terms: data.payment_terms || prev.payment_terms,
                terms: data.terms || prev.terms,
                notes: data.notes || prev.notes,
                duration: data.duration || prev.duration,
                key_features: data.key_features || prev.key_features,
                pricing_items: data.pricing_items || prev.pricing_items,
                total_amount: data.total_amount || prev.total_amount,
            }));

            setActiveTab('scope');
        } catch (error) {
            console.error('AI Generation Failed:', error);
            alert('Failed to generate contract from AI. Check the console for errors.');
        } finally {
            setIsGenerating(false);
        }
    };

    const handleGenerateInvoice = () => {
        const title = prompt("Enter milestone title:");
        if (!title) return;
        const amount = prompt("Enter amount for this milestone:");
        if (!amount || isNaN(Number(amount))) return alert("Invalid amount");

        router.post(route('projects.contracts.invoice', { project: project.id, contract: contract.id }), {
            title,
            amount,
            description: `Milestone for ${project.project_name}`
        }, {
            onSuccess: () => {
                alert("Invoice generated successfully");
            }
        });
    };

    const onSubmit = (e) => {
        e.preventDefault();
        setIsLoading(true);

        const routeName = contract 
            ? 'projects.contracts.update' 
            : 'projects.contracts.store';

        const params = contract 
            ? { project: project.id, contract: contract.id }
            : { project: project.id };

        const action = contract ? router.put : router.post;

        action(route(routeName, params), formData, {
            onSuccess: () => {
                setIsLoading(false);
                onClose();
            },
            onError: () => {
                setIsLoading(false);
            }
        });
    };

    const addFeature = () => setFormData(p => ({ ...p, key_features: [...p.key_features, ''] }));
    const updateFeature = (i, val) => setFormData(p => {
        const nf = [...p.key_features];
        nf[i] = val;
        return { ...p, key_features: nf };
    });
    const removeFeature = (i) => setFormData(p => ({
        ...p, key_features: p.key_features.filter((_, idx) => idx !== i)
    }));

    const addPricing = () => setFormData(p => ({ 
        ...p, 
        pricing_items: [...p.pricing_items, { item: '', description: '', hours: 0, hourly_rate: 0, total: 0 }] 
    }));
    const updatePricing = (i, field, val) => setFormData(p => {
        const np = [...p.pricing_items];
        np[i][field] = val;
        if (field === 'hours' || field === 'hourly_rate') {
            np[i].total = (np[i].hours || 0) * (np[i].hourly_rate || 0);
        }
        return { ...p, pricing_items: np };
    });
    const removePricing = (i) => setFormData(p => ({
        ...p, pricing_items: p.pricing_items.filter((_, idx) => idx !== i)
    }));

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                    <DialogTitle>{contract ? 'Edit Contract / Proposal' : 'Create New Contract / Proposal'}</DialogTitle>
                </DialogHeader>

                <div className="flex border-b mb-4">
                    <button 
                        className={`px-4 py-2 font-medium text-sm ${activeTab === 'details' ? 'border-b-2 border-indigo-500 text-indigo-600' : 'text-slate-500'}`}
                        onClick={() => setActiveTab('details')}
                    >
                        General Details
                    </button>
                    <button 
                        className={`px-4 py-2 font-medium text-sm ${activeTab === 'scope' ? 'border-b-2 border-indigo-500 text-indigo-600' : 'text-slate-500'}`}
                        onClick={() => setActiveTab('scope')}
                    >
                        Scope & Features
                    </button>
                    <button 
                        className={`px-4 py-2 font-medium text-sm ${activeTab === 'pricing' ? 'border-b-2 border-indigo-500 text-indigo-600' : 'text-slate-500'}`}
                        onClick={() => setActiveTab('pricing')}
                    >
                        Pricing & Milestones
                    </button>
                    {contract && (
                        <button 
                            className={`px-4 py-2 font-medium text-sm ${activeTab === 'ai' ? 'border-b-2 border-indigo-500 text-indigo-600' : 'text-slate-500'} ml-auto flex items-center gap-1`}
                            onClick={() => setActiveTab('ai')}
                        >
                            <Sparkles className="w-3 h-3" /> AI Assistant
                        </button>
                    )}
                </div>

                {!contract && activeTab === 'details' && (
                    <div className="bg-indigo-50 p-4 rounded-lg mb-6 border border-indigo-100 flex flex-col gap-3">
                        <div className="flex items-center gap-2 text-indigo-800 font-semibold">
                            <Sparkles className="w-5 h-5" /> Generate with AI (Recommended)
                        </div>
                        <Textarea 
                            placeholder="Describe the project requirements, features, timeline, and pricing... The AI will structure the contract for you." 
                            value={aiPrompt}
                            onChange={(e) => setAiPrompt(e.target.value)}
                            className="bg-white border-indigo-200"
                            rows={3}
                        />
                        <Button 
                            onClick={handleGenerateAi} 
                            disabled={isGenerating} 
                            className="self-end bg-indigo-600 hover:bg-indigo-700 text-white"
                        >
                            {isGenerating ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Generating...</> : 'Generate Contract'}
                        </Button>
                    </div>
                )}

                <form id="contract-form" onSubmit={onSubmit} className="space-y-6">
                    {activeTab === 'details' && (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div className="md:col-span-2">
                                <Label>Project Description / Objective</Label>
                                <Textarea 
                                    value={formData.description} 
                                    onChange={e => setFormData({...formData, description: e.target.value})}
                                    rows={4}
                                    placeholder="Executive summary of the project..."
                                />
                            </div>
                            <div>
                                <Label>Currency</Label>
                                <select 
                                    className="flex h-10 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm ring-offset-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-slate-950 focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                                    value={formData.currency_id}
                                    onChange={e => setFormData({...formData, currency_id: e.target.value})}
                                    required
                                >
                                    <option value="">Select Currency</option>
                                    {currencies.map(c => (
                                        <option key={c.id} value={c.id}>{c.currency} ({c.symbol})</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <Label>Total Amount</Label>
                                <Input 
                                    type="number" 
                                    step="0.01" 
                                    value={formData.total_amount} 
                                    onChange={e => setFormData({...formData, total_amount: e.target.value})}
                                    required
                                />
                            </div>
                            <div>
                                <Label>Duration (e.g., 3 Months)</Label>
                                <Input 
                                    value={formData.duration} 
                                    onChange={e => setFormData({...formData, duration: e.target.value})}
                                />
                            </div>
                            <div>
                                <Label>Valid Until</Label>
                                <Input 
                                    type="date" 
                                    value={formData.valid_until} 
                                    onChange={e => setFormData({...formData, valid_until: e.target.value})}
                                />
                            </div>
                            {contract && (
                                <div>
                                    <Label>Contract Status</Label>
                                    <select 
                                        className="flex h-10 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm"
                                        value={formData.status}
                                        onChange={e => setFormData({...formData, status: e.target.value})}
                                    >
                                        <option value="draft">Draft</option>
                                        <option value="sent">Sent</option>
                                        <option value="active">Active</option>
                                        <option value="completed">Completed</option>
                                    </select>
                                </div>
                            )}
                        </div>
                    )}

                    {activeTab === 'scope' && (
                        <div className="space-y-4">
                            <div>
                                <div className="flex justify-between items-center mb-2">
                                    <Label className="text-base font-semibold">Key Features / Scope of Work</Label>
                                    <Button type="button" variant="outline" size="sm" onClick={addFeature}>
                                        <Plus className="w-4 h-4 mr-1" /> Add Feature
                                    </Button>
                                </div>
                                <div className="space-y-2">
                                    {formData.key_features.map((feature, idx) => (
                                        <div key={idx} className="flex items-center gap-2">
                                            <Input 
                                                value={feature} 
                                                onChange={e => updateFeature(idx, e.target.value)} 
                                                placeholder={`Feature ${idx + 1}`}
                                            />
                                            <Button type="button" variant="ghost" size="icon" onClick={() => removeFeature(idx)} className="text-red-500 hover:bg-red-50 hover:text-red-700">
                                                <Trash2 className="w-4 h-4" />
                                            </Button>
                                        </div>
                                    ))}
                                    {formData.key_features.length === 0 && (
                                        <div className="text-center p-4 border border-dashed rounded text-slate-500 text-sm">
                                            No features added. Click "Add Feature" or use AI to generate.
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="pt-4 border-t">
                                <Label className="text-base font-semibold block mb-2">General Terms & Conditions</Label>
                                <Textarea 
                                    value={formData.terms} 
                                    onChange={e => setFormData({...formData, terms: e.target.value})}
                                    rows={6}
                                    placeholder="Legal terms, responsibilities, etc..."
                                />
                            </div>
                        </div>
                    )}

                    {activeTab === 'pricing' && (
                        <div className="space-y-4">
                            <div>
                                <div className="flex justify-between items-center mb-2">
                                    <Label className="text-base font-semibold">Pricing Items (Quotation)</Label>
                                    <Button type="button" variant="outline" size="sm" onClick={addPricing}>
                                        <Plus className="w-4 h-4 mr-1" /> Add Item
                                    </Button>
                                </div>
                                <div className="space-y-3">
                                    {formData.pricing_items.map((item, idx) => (
                                        <div key={idx} className="flex items-start gap-2 bg-slate-50 p-3 rounded border">
                                            <div className="grid grid-cols-1 md:grid-cols-4 gap-2 flex-1">
                                                <div className="md:col-span-4">
                                                    <Input placeholder="Item Title" value={item.item} onChange={e => updatePricing(idx, 'item', e.target.value)} />
                                                </div>
                                                <div className="md:col-span-4">
                                                    <Input placeholder="Description" value={item.description} onChange={e => updatePricing(idx, 'description', e.target.value)} />
                                                </div>
                                                <div>
                                                    <Label className="text-xs">Hours/Qty</Label>
                                                    <Input type="number" placeholder="Hours" value={item.hours} onChange={e => updatePricing(idx, 'hours', e.target.value)} />
                                                </div>
                                                <div>
                                                    <Label className="text-xs">Rate</Label>
                                                    <Input type="number" placeholder="Rate" value={item.hourly_rate} onChange={e => updatePricing(idx, 'hourly_rate', e.target.value)} />
                                                </div>
                                                <div className="md:col-span-2">
                                                    <Label className="text-xs">Line Total</Label>
                                                    <Input type="number" disabled value={item.total} className="bg-slate-100" />
                                                </div>
                                            </div>
                                            <Button type="button" variant="ghost" size="icon" onClick={() => removePricing(idx)} className="text-red-500 mt-6">
                                                <Trash2 className="w-4 h-4" />
                                            </Button>
                                        </div>
                                    ))}
                                    {formData.pricing_items.length === 0 && (
                                        <div className="text-center p-4 border border-dashed rounded text-slate-500 text-sm">
                                            No pricing items added.
                                        </div>
                                    )}
                                </div>
                            </div>

                            <div className="pt-4 border-t">
                                <Label className="text-base font-semibold block mb-2">Payment Terms (Milestones)</Label>
                                <Textarea 
                                    value={formData.payment_terms} 
                                    onChange={e => setFormData({...formData, payment_terms: e.target.value})}
                                    rows={4}
                                    placeholder="e.g. 50% upfront, 25% after UI, 25% upon delivery..."
                                />
                            </div>

                            {contract && (
                                <div className="pt-4 border-t flex items-center justify-between">
                                    <div className="text-sm text-slate-600">
                                        You can generate invoices dynamically from the contract milestones.
                                    </div>
                                    <Button type="button" variant="outline" onClick={handleGenerateInvoice}>
                                        <Send className="w-4 h-4 mr-2" /> Generate Invoice
                                    </Button>
                                </div>
                            )}
                        </div>
                    )}

                    {activeTab === 'ai' && contract && (
                        <div className="bg-indigo-50 p-4 rounded-lg mb-6 border border-indigo-100 flex flex-col gap-3">
                            <div className="flex items-center gap-2 text-indigo-800 font-semibold">
                                <Sparkles className="w-5 h-5" /> Refine with AI
                            </div>
                            <p className="text-sm text-indigo-700 mb-2">
                                Describe the changes you want to make to this contract (e.g., "Add a milestone for testing", "Change the duration to 6 months and adjust pricing accordingly"). The AI will create a new version.
                            </p>
                            <Textarea 
                                placeholder="Instructions for AI..." 
                                value={aiPrompt}
                                onChange={(e) => setAiPrompt(e.target.value)}
                                className="bg-white border-indigo-200"
                                rows={3}
                            />
                            <Button 
                                onClick={handleGenerateAi} 
                                disabled={isGenerating} 
                                className="self-end bg-indigo-600 hover:bg-indigo-700 text-white"
                            >
                                {isGenerating ? <><Loader2 className="w-4 h-4 mr-2 animate-spin" /> Processing...</> : 'Refine Contract'}
                            </Button>
                        </div>
                    )}

                </form>

                <DialogFooter className="mt-6 border-t pt-4">
                    <Button variant="outline" onClick={onClose} type="button">Cancel</Button>
                    <Button type="submit" form="contract-form" disabled={isLoading || isGenerating}>
                        {isLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : null}
                        {contract ? 'Update Contract (Creates new version)' : 'Create Contract'}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    );
}

import React, { useState } from 'react';
import { Head, Link, router } from '@inertiajs/react';
import { Copy, Mail, MessageCircle, ChevronDown, Key, Wallet, FileText, Briefcase, Trash2, Edit, ShieldCheck, Plus } from 'lucide-react';
import AdminSidebarLayout from '@/Layouts/AdminSidebarLayout';
import HiddenAmount from '@/Components/HiddenAmount';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
    DropdownMenuGroup,
} from "@/Components/ui/dropdown-menu";
import {
    Dialog,
    DialogContent,
    DialogDescription,
    DialogFooter,
    DialogHeader,
    DialogTitle,
} from "@/Components/ui/dialog";
import { Button } from '@/Components/ui/button';
import { Input } from '@/Components/ui/input';
import { Label } from '@/Components/ui/label';
import { formatMoney as formatCurrency } from '@/lib/utils';
import { __ } from '@/lib/i18n';
import UserLoansTab from './UserLoansTab';

export default function Show({ client, loans = [], stats = {}, wallets, modulePlans = [], subscriptions = [] }) {
    const [isLoginAsLoading, setIsLoginAsLoading] = useState(false);
    const [isResetPassOpen, setIsResetPassOpen] = useState(false);
    const [newPassword, setNewPassword] = useState('');
    const [isChangeRoleOpen, setIsChangeRoleOpen] = useState(false);
    const [selectedRole, setSelectedRole] = useState(client.role || 'client');
    
    // New Modal States
    const [isDeleteUserOpen, setIsDeleteUserOpen] = useState(false);
    const [isActivateMembershipOpen, setIsActivateMembershipOpen] = useState(false);
    const [isFinanceModalOpen, setIsFinanceModalOpen] = useState(false);



    const handleLoginAsUser = async () => {
        setIsLoginAsLoading(true);
        try {
            const res = await window.axios.post(`/admin/users/${client.id}/login-as`);
            window.location.href = res.data.redirect_url;
        } catch (e) {
            alert('Failed to impersonate user.');
        } finally {
            setIsLoginAsLoading(false);
        }
    };

    const handleResetPassword = async () => {
        try {
            const res = await window.axios.post(`/admin/users/${client.id}/generate-password`);
            setNewPassword(res.data.new_password);
        } catch (e) {
            alert('Failed to reset password.');
        }
    };

    const submitChangeRole = (e) => {
        e.preventDefault();
        router.post(`/admin/users/${client.id}/update-role`, { role: selectedRole }, {
            onSuccess: () => {
                setIsChangeRoleOpen(false);
                alert(__("general.user_role_updated_successfully"));
            }
        });
    };



    const submitDeleteUser = (e) => {
        e.preventDefault();
        router.delete(`/admin/users/${client.id}`, {
            onSuccess: () => {
                setIsDeleteUserOpen(false);
            }
        });
    };

    const [membershipForm, setMembershipForm] = useState({ 
        object: modulePlans.length > 0 ? modulePlans[0].id : '', 
        duration_days: '1' 
    });
    const submitActivateMembership = (e) => {
        e.preventDefault();
        router.post(`/admin/users/${client.id}/membership`, membershipForm, {
            onSuccess: () => {
                setIsActivateMembershipOpen(false);
                setMembershipForm({ object: modulePlans.length > 0 ? modulePlans[0].id : '', duration_days: '1' });
                alert("Membership activated successfully!");
            }
        });
    };

    const [isEditMembershipOpen, setIsEditMembershipOpen] = useState(false);
    const [editMembershipForm, setEditMembershipForm] = useState({
        id: '',
        status: 'active',
        expires_at: ''
    });

    const openEditMembership = (sub) => {
        setEditMembershipForm({
            id: sub.id,
            status: sub.status,
            expires_at: sub.expires_at ? sub.expires_at.split('T')[0] : ''
        });
        setIsEditMembershipOpen(true);
    };

    const submitEditMembership = (e) => {
        e.preventDefault();
        router.put(`/admin/users/${client.id}/membership/${editMembershipForm.id}`, editMembershipForm, {
            onSuccess: () => {
                setIsEditMembershipOpen(false);
                alert("Membership updated successfully!");
            }
        });
    };

    const deleteMembership = (subId) => {
        if (confirm("Are you sure you want to delete this subscription?")) {
            router.delete(`/admin/users/${client.id}/membership/${subId}`, {
                onSuccess: () => {
                    alert("Membership deleted successfully!");
                }
            });
        }
    };

    const referralCode = client.slug || client.id;
    const referralLink = `${window.location.origin}/r/${referralCode}`;

    const copyToClipboard = (text) => {
        navigator.clipboard.writeText(text);
        alert('Copied to clipboard!');
    };

    return (
        <AdminSidebarLayout title={`User Profile: ${client.name}`} header="User Details">
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-3xl font-bold font-sora">{__('general.user_profile')}</h1>
                
                <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                    <div role="button" className="inline-flex cursor-pointer items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-[8px] hover:bg-slate-800 transition shadow-sm text-sm font-semibold select-none">{__('general.quick_actions')}<ChevronDown size={16} />
                    </div>
                </DropdownMenuTrigger>
                    <DropdownMenuContent align="end" className="w-[calc(100vw-2rem)] md:w-[750px] p-4 max-h-[85vh] overflow-y-auto">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            {/* Column 1: Profile & Security */}
                            <div className="space-y-1">
                                <DropdownMenuLabel className="text-slate-500 uppercase tracking-wider text-xs mb-2">{__('general.profile_and_security') || 'Profile & Security'}</DropdownMenuLabel>
                                <DropdownMenuGroup>
                                    <DropdownMenuItem onClick={handleLoginAsUser} disabled={isLoginAsLoading}>
                                        <Briefcase className="mr-2 h-4 w-4" />
                                        <span>{isLoginAsLoading ? __('general.logging_in') : __('general.login_as')}</span>
                                    </DropdownMenuItem>
                                    <DropdownMenuItem asChild>
                                        <Link href={`/admin/users/${client.id}/edit`} className="w-full cursor-pointer flex items-center">
                                            <Edit className="mr-2 h-4 w-4" />
                                            <span>{__('general.edit_profile')}</span>
                                        </Link>
                                    </DropdownMenuItem>
                                    <DropdownMenuItem onClick={() => { setIsResetPassOpen(true); setNewPassword(''); }}>
                                        <Key className="mr-2 h-4 w-4" />
                                        <span>{__('general.reset_password')}</span>
                                    </DropdownMenuItem>
                                    <DropdownMenuItem onClick={() => { setSelectedRole(client.role || 'client'); setIsChangeRoleOpen(true); }}>
                                        <ShieldCheck className="mr-2 h-4 w-4" />
                                        <span>{__('general.change_role')}</span>
                                    </DropdownMenuItem>
                                </DropdownMenuGroup>
                                
                                <div className="pt-4 mt-4 border-t border-slate-100"></div>
                                <DropdownMenuGroup>
                                    <DropdownMenuItem className="text-red-600 focus:bg-red-50 focus:text-red-700" onClick={() => setIsDeleteUserOpen(true)}>
                                        <Trash2 className="mr-2 h-4 w-4" />
                                        <span>{__('general.delete_user')}</span>
                                    </DropdownMenuItem>
                                </DropdownMenuGroup>
                            </div>

                            {/* Column 2: Workspace & Tools */}
                            <div className="space-y-1">
                                <DropdownMenuLabel className="text-slate-500 uppercase tracking-wider text-xs mb-2">{__('general.workspace_and_tools') || 'Workspace & Tools'}</DropdownMenuLabel>
